module aladin_device (\n    input clk,\n    input rst_n,\n    input start,\n    input [1:0] cmd_type,\n    input [15:0] L,\n    input [15:0] R,\n    input [19:0] A,\n    input [19:0] B,\n    output reg [31:0] result,\n    output reg done\n);\n\n    parameter BOXES = 16;\n    reg [31:0] box [1:BOXES];\n\n    localparam [1:0] IDLE  = 2'd0;\n    localparam [1:0] UPDATE = 2'd1;\n    localparam [1:0] QUERY  = 2'd2;\n\n    reg [1:0] state;\n    reg [15:0] current_index;\n    reg [15:0] step;\n    reg [31:0] sum;\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            for (i = 1; i <= BOXES; i = i + 1) begin\n                box[i] <= 32'd0;\n            end\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            current_index <= 16'd0;\n            step <= 16'd0;\n            sum <= 32'd0;\n        end else begin\n            done <= 1'b0;\n\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        if (cmd_type == 2'd1) begin\n                            current_index <= L;\n                            step <= 16'd1;\n                            state <= UPDATE;\n                        end else if (cmd_type == 2'd2) begin\n                            current_index <= L;\n                            sum <= 32'd0;\n                            state <= QUERY;\n                        end\n                    end\n                end\n\n                UPDATE: begin\n                    if (current_index <= R && current_index >= 16'd1 && current_index <= BOXES) begin\n                        box[current_index] <= (step * A) % B;\n                        current_index <= current_index + 16'd1;\n                        step <= step + 16'd1;\n                    end else begin\n                        state <= IDLE;\n                        done <= 1'b1;\n                    end\n                end\n\n                QUERY: begin\n                    if (current_index <= R && current_index >= 16'd1 && current_index <= BOXES) begin\n                        sum <= sum + box[current_index];\n                        current_index <= current_index + 16'd1;\n                    end else begin\n                        state <= IDLE;\n                        result <= sum;\n                        done <= 1'b1;\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule